import { useCallback, useEffect, useRef } from 'react';

// USGS GeoJSON feeds — significant quakes past 30 days
const USGS_URL   = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_month.geojson';
const REFRESH_MS = 10 * 60_000; // 10 minutes

interface EqFeature {
  id: string;
  geometry: { coordinates: [number, number, number] };
  properties: {
    mag:   number;
    place: string;
    time:  number;
    type:  string;
  };
}

function magColor(mag: number): string {
  if (mag < 2)  return '#3fb950';
  if (mag < 3)  return '#7ee787';
  if (mag < 4)  return '#d29922';
  if (mag < 5)  return '#f0883e';
  if (mag < 6)  return '#f85149';
  return '#ff4444';
}

function magRadius(mag: number): number {
  // Exponential scaling: M2 ≈ 4px, M5 ≈ 12px, M8 ≈ 30px
  return Math.min(40, Math.max(3, Math.pow(2, mag - 1) * 1.5));
}

function ageLabel(ms: number): string {
  const h = Math.round(ms / 3_600_000);
  if (h < 1)  return '<1 h ago';
  if (h < 24) return `${h} h ago`;
  return `${Math.round(h / 24)} d ago`;
}

interface EarthquakeLayerProps {
  map:     import('leaflet').Map | null;
  enabled: boolean;
}

export function EarthquakeLayer({ map, enabled }: EarthquakeLayerProps) {
  const circlesRef = useRef<Map<string, import('leaflet').CircleMarker>>(new Map());

  const clearAll = useCallback(() => {
    circlesRef.current.forEach((c) => c.remove());
    circlesRef.current.clear();
  }, []);

  const fetchAndRender = useCallback(async () => {
    if (!map || !enabled) return;

    try {
      const res = await fetch(USGS_URL);
      if (!res.ok) return;
      const data = await res.json() as { features: EqFeature[] };
      if (!map || !enabled) return;

      const L   = window.L;
      const now = Date.now();
      const seen = new Set<string>();

      for (const f of data.features) {
        const [lng, lat, depthKm] = f.geometry.coordinates;
        const { mag, place, time, type } = f.properties;
        if (type !== 'earthquake' || mag == null || lat == null || lng == null) continue;

        seen.add(f.id);
        const age    = now - time;
        const color  = magColor(mag);
        const radius = magRadius(mag);

        if (circlesRef.current.has(f.id)) continue; // already rendered

        const circle = L.circleMarker([lat, lng], {
          radius,
          color,
          fillColor:   color,
          fillOpacity: Math.max(0.25, 0.7 - age / (30 * 24 * 3_600_000)), // fade with age
          weight:      1,
        });

        circle.bindPopup(`
          <div style="font-family:monospace;font-size:12px;line-height:1.75;min-width:190px;">
            <div style="font-weight:700;font-size:13px;color:${color};margin-bottom:4px">
              M${mag.toFixed(1)} Earthquake
            </div>
            <div>📍 ${place}</div>
            <div>🕐 ${ageLabel(age)}</div>
            <div>↓ Depth: ${Math.round(depthKm)} km</div>
          </div>`, { maxWidth: 250 });

        circle.addTo(map);
        circlesRef.current.set(f.id, circle);
      }

      // Remove entries no longer in the feed
      circlesRef.current.forEach((c, id) => {
        if (!seen.has(id)) { c.remove(); circlesRef.current.delete(id); }
      });
    } catch {
      // ignore
    }
  }, [map, enabled]);

  useEffect(() => {
    if (!enabled) { clearAll(); return; }

    fetchAndRender();
    const id = setInterval(fetchAndRender, REFRESH_MS);
    return () => { clearInterval(id); clearAll(); };
  }, [enabled, fetchAndRender, clearAll]);

  return null;
}
